def _collect_pipeline_files(repo, targets: list[str], props, onerror=None):
    result: dict[str, dict] = {}
    top_plots = repo.index._plots

    # Process each dvcfile
    for dvcfile, plots_def in top_plots.items():
        dvcfile_path = _relpath(repo.dvcfs, dvcfile)

        # First, collect all plot definitions and group them by their target path
        path_to_props = {}

        for elem in plots_def:
            if isinstance(elem, str):
                # Simple path with no properties
                path = elem
                plot_props = None
            else:
                # Path with properties
                assert elem
                path, plot_props = next(iter(elem.items()))

            # Store the properties for this path
            path_to_props[path] = plot_props

        # Process paths from most specific (longest) to least specific (shortest)
        # This ensures subdirectory configs are processed first
        paths_sorted_by_specificity = sorted(path_to_props.keys(), key=len, reverse=True)

        # Process each path separately to avoid parent configs overwriting subdirectory configs
        for path in paths_sorted_by_specificity:
            plot_props = path_to_props[path]

            # Create a dictionary with just this path
            single_path_dict = {path: plot_props}

            # Resolve and merge this path's definitions
            resolved = _resolve_definitions(
                repo.dvcfs, targets, props, dvcfile_path, single_path_dict, onerror=onerror
            )

            # Merge the resolved definitions into the result
            if dvcfile_path not in result:
                result[dvcfile_path] = {}

            # Merge without overwriting existing keys (which would be more specific paths)
            if "data" in resolved:
                if "data" not in result[dvcfile_path]:
                    result[dvcfile_path]["data"] = {}

                for file_path, file_props in resolved["data"].items():
                    # Only add if the file path doesn't already exist in the result
                    # or if it's not a subdirectory of an existing path
                    if file_path not in result[dvcfile_path]["data"]:
                        result[dvcfile_path]["data"][file_path] = file_props

    return result
